package com.day18.auth.service; import com.day18.auth.model.User; import com.day18.auth.repo.UserRepository; import com.day18.auth.security.JwtService; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import java.util.Map;
@Service public class AuthService { final UserRepository repo; final PasswordEncoder enc; final JwtService jwt; public AuthService(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} public void register(String u,String p){if(repo.findByUsername(u).isPresent())throw new IllegalArgumentException("username already exists"); User x=new User(u,enc.encode(p));repo.save(x);} public Map<String,String> login(String u,String p){User x=repo.findByUsername(u).orElseThrow(()->new IllegalArgumentException("invalid credentials"));if(!enc.matches(p,x.passwordHash))throw new IllegalArgumentException("invalid credentials");return Map.of("accessToken",jwt.create(x.username,x.role),"tokenType","Bearer","expiresIn","3600");}}
